def assert_fallback_storage_recovery_mode(metadata: dict[str, Any], label: str) -> None:
    if metadata.get("storage_recovery_mode") != EXPECTED_FALLBACK_STORAGE_RECOVERY_MODE:
        raise SystemExit(f"{label} missed fallback storage recovery mode: {metadata}")
    if metadata.get("storage_recovery_next_operator_action") != EXPECTED_FALLBACK_STORAGE_NEXT_ACTION:
        raise SystemExit(f"{label} missed fallback storage next operator action: {metadata}")
    if metadata.get("storage_recovery_restart_required") is not True:
        raise SystemExit(f"{label} should require restart after fallback storage recovery: {metadata}")


def assert_storage_handoff_contract(payload: dict[str, Any], label: str, expected_source: str) -> None:
    handoff = payload.get("storage_handoff")
    if not isinstance(handoff, dict) or not handoff:
        raise SystemExit(f"{label} missed compact storage_handoff: {payload}")
    if handoff.get("source") != expected_source:
        raise SystemExit(f"{label} storage_handoff source diverged: {handoff}")
    for key in ["handoff_ready", "storage_handoff_ready", "ready_for_operator"]:
        if handoff.get(key) is not True:
            raise SystemExit(f"{label} storage_handoff should report {key}=True: {handoff}")
    for key in ["state_changed", "authorizes_execution", "authorizes_completion_claim", "approval_granted"]:
        if handoff.get(key) is not False:
            raise SystemExit(f"{label} storage_handoff should report {key}=False: {handoff}")
    boundaries = handoff.get("boundaries") or {}
    for key in [
        "metadata_only",
    ]:
        if boundaries.get(key) is not True:
            raise SystemExit(f"{label} storage_handoff boundary {key} should be true: {handoff}")
    for key in [
        "reads_database_file",
        "reads_db_file_contents",
        "reads_vault_files",
        "scans_obsidian_vault",
        "writes_files",
        "writes_database",
        "writes_memory",
        "writes_notes",
        "queues_approval",
        "approves_request",
        "approves_requests",
        "dismisses_request",
        "dismisses_approvals",
        "controls_computer",
        "calls_external_service",
        "executes_tools",
        "authorizes_execution",
        "authorizes_completion_claim",
    ]:
        if boundaries.get(key) is not False:
            raise SystemExit(f"{label} storage_handoff boundary {key} should be false: {handoff}")
    for key in [
        "storage_readiness_blocks_completion_claim",
        "storage_recovery_required",
        "storage_recovery_mode",
        "storage_recovery_next_operator_action",
        "storage_recovery_restart_required",
        "storage_readiness_next_commands",
        "storage_readiness_next_required_command",
        "storage_readiness_next_proof_command",
        "storage_readiness_proof_queue",
        "storage_readiness_first_proof_command",
        "storage_recovery_check_tool_command",
        "storage_recovery_check_command",
        "storage_recovery_command",
        "storage_issue_count",
    ]:
        if handoff.get(key) != payload.get(key):
            raise SystemExit(f"{label} storage_handoff field {key} diverged from top-level field: {handoff}")
    if handoff.get("storage_readiness_next_command_count") != len(handoff.get("storage_readiness_next_commands") or []):
        raise SystemExit(f"{label} storage_handoff readiness queue/count diverged: {handoff}")
    if handoff.get("storage_readiness_proof_queue_count") != len(handoff.get("storage_readiness_proof_queue") or []):
        raise SystemExit(f"{label} storage_handoff proof queue/count diverged: {handoff}")
    if handoff.get("next_proof_command") != payload.get("storage_readiness_next_proof_command"):
        raise SystemExit(f"{label} storage_handoff missed storage next proof command: {handoff}")
    if handoff.get("storage_readiness_next_required_command") != payload.get("storage_readiness_next_required_command"):
        raise SystemExit(f"{label} storage_handoff missed storage next required command: {handoff}")
    if payload.get("storage_readiness_next_required_command") != payload.get("storage_readiness_next_proof_command"):
        raise SystemExit(f"{label} storage next required/proof commands diverged: {payload}")


def stale_checkpoint_recovery_execute_approval_queue_metadata(
    metadata: dict[str, Any],
) -> dict[str, Any]:
    handoff = metadata.get("checkpoint_recovery_execute_handoff") or {}
    proof_queue = list(metadata.get("recovery_step_approval_proof_queue") or [])
    stale_queue = list(proof_queue) or ["stale recovery approval proof"]
    stale_queue[-1] = "stale checkpoint recovery approval proof"
    risk_signals = [str(signal) for signal in (metadata.get("risky_recovery_signals") or [])]
    step_sha256 = str(metadata.get("recovery_step_sha256") or "")
    verification_sha256 = str(metadata.get("recovery_verification_sha256") or "")
    approval_reference = (
        str(metadata.get("approval_reference") or "")
        if metadata.get("approval_reference_provided")
        else ""
    )
    stale_rows = _approval_boundary_rows_for_risky_work(
        risk_signals=risk_signals,
        step_sha256=step_sha256,
        verification_sha256=verification_sha256,
        proof_queue=stale_queue,
        required_field="required_before_risky_recovery_step",
    )
    stale_token = _risky_recovery_step_approval_boundary_token_sha256(
        recovery_step_sha256=step_sha256,
        recovery_verification_sha256=verification_sha256,
        risk_signals=risk_signals,
        approval_proof_queue=stale_queue,
        approval_boundary_rows=stale_rows,
        approval_reference=approval_reference,
    )
    stale_ready = _recovery_step_approval_boundary_ready(
        token_sha256=stale_token,
        recovery_step_sha256=step_sha256,
        recovery_verification_sha256=verification_sha256,
        approval_proof_queue=stale_queue,
        approval_boundary_rows=stale_rows,
        approval_reference=approval_reference,
    )
    stale_prior = _recovery_step_approval_boundary_ready(
        token_sha256=stale_token,
        recovery_step_sha256=step_sha256,
        recovery_verification_sha256=verification_sha256,
        approval_proof_queue=stale_queue,
        approval_boundary_rows=stale_rows,
        approval_reference=approval_reference,
        require_prior_proof=True,
    )
    stale_metadata = dict(metadata)
    stale_handoff = dict(handoff)
    stale_next = stale_queue[0] if stale_queue else ""
    top_updates = {
        "recovery_step_approval_proof_queue": stale_queue,
        "recovery_step_approval_proof_queue_count": len(stale_queue),
        "recovery_step_next_approval_proof_command": stale_next,
        "recovery_step_approval_boundary_rows": stale_rows,
        "recovery_step_approval_boundary_row_count": len(stale_rows),
        "recovery_step_approval_boundary_ready": stale_ready,
        "recovery_step_approval_boundary_token_sha256": stale_token,
        "recovery_step_approval_boundary_token_present": True,
        "recovery_step_approval_boundary_as_prior_proof": stale_prior,
    }
    flat_updates = {
        "checkpoint_recovery_execute_handoff_recovery_step_approval_proof_queue": stale_queue,
        "checkpoint_recovery_execute_handoff_recovery_step_approval_proof_queue_count": len(stale_queue),
        "checkpoint_recovery_execute_handoff_recovery_step_next_approval_proof_command": stale_next,
        "checkpoint_recovery_execute_handoff_recovery_step_approval_boundary_rows": stale_rows,
        "checkpoint_recovery_execute_handoff_recovery_step_approval_boundary_row_count": len(stale_rows),
        "checkpoint_recovery_execute_handoff_recovery_step_approval_boundary_ready": stale_ready,
        "checkpoint_recovery_execute_handoff_recovery_step_approval_boundary_token_sha256": stale_token,
        "checkpoint_recovery_execute_handoff_recovery_step_approval_boundary_token_present": True,
        "checkpoint_recovery_execute_handoff_recovery_step_approval_boundary_as_prior_proof": stale_prior,
    }
    stale_metadata.update(top_updates)
    stale_metadata.update(flat_updates)
    stale_handoff.update(top_updates)
    stale_handoff["handoff_token_sha256"] = _checkpoint_recovery_execute_handoff_token_sha256(
        stale_handoff
    )
    stale_metadata["checkpoint_recovery_execute_handoff"] = stale_handoff
    stale_metadata["checkpoint_recovery_execute_handoff_token_sha256"] = stale_handoff[
        "handoff_token_sha256"
    ]
    return stale_metadata


def assert_checkpoint_recovery_execute_rejects_stale_approval_queue(
    metadata: dict[str, Any],
    label: str,
) -> None:
    stale_metadata = stale_checkpoint_recovery_execute_approval_queue_metadata(metadata)
    if _checkpoint_recovery_execute_handoff_ready(stale_metadata):
        raise SystemExit(
            f"{label} checkpoint recovery execute validator accepted coordinated stale approval proof queue."
        )


def assert_checkpoint_recovery_execute_rejects_stale_precontinuation_mirrors(
    metadata: dict[str, Any],
    label: str,
) -> None:
    tampers = [
        ("operator_timebox_precontinuation_contract_ready", False),
        ("operator_timebox_precontinuation_contract_state", "TAMPERED_TIMEBOX_STATE"),
        ("operator_timebox_precontinuation_allows_continuation", not bool(metadata.get("operator_timebox_precontinuation_allows_continuation"))),
        ("operator_timebox_precontinuation_blocks_continuation", not bool(metadata.get("operator_timebox_precontinuation_blocks_continuation"))),
        ("operator_timebox_precontinuation_requires_stop", not bool(metadata.get("operator_timebox_precontinuation_requires_stop"))),
        ("operator_timebox_precontinuation_requires_fresh_timebox_review", False),
        ("operator_timebox_precontinuation_allowed_states", ["STOP_WINDOW_ACTIVE"]),
        ("operator_supersession_precontinuation_contract_ready", False),
        ("operator_supersession_precontinuation_contract_state", "TAMPERED_SUPERSESSION_STATE"),
        ("operator_supersession_precontinuation_token_boundary_ready", False),
        ("operator_supersession_precontinuation_allows_continuation", not bool(metadata.get("operator_supersession_precontinuation_allows_continuation"))),
        ("operator_supersession_precontinuation_blocks_continuation", not bool(metadata.get("operator_supersession_precontinuation_blocks_continuation"))),
        ("operator_supersession_precontinuation_requires_stop", not bool(metadata.get("operator_supersession_precontinuation_requires_stop"))),
        ("operator_supersession_precontinuation_requires_fresh_latest_instruction_review", False),
        ("operator_supersession_precontinuation_allowed_states", ["LATEST_INSTRUCTION_READY_TO_GOVERN_CONTINUATION"]),
    ]
    for key, tampered_value in tampers:
        missing_metadata = dict(metadata)
        missing_metadata.pop(key, None)
        if _checkpoint_recovery_execute_handoff_ready(missing_metadata):
            raise SystemExit(
                f"{label} checkpoint recovery execute validator accepted missing pre-continuation mirror {key}."
            )
        tampered_metadata = dict(metadata)
        tampered_metadata[key] = tampered_value
        if _checkpoint_recovery_execute_handoff_ready(tampered_metadata):
            raise SystemExit(
                f"{label} checkpoint recovery execute validator accepted tampered pre-continuation mirror {key}."
            )
