STATUS_SMOKE_PRINT_LIMIT = 4000
STATUS_SMOKE_REAL_SERVER_ENV = "JARVIS_STATUS_SMOKE_REAL_SERVER"
STATUS_SMOKE_PRINT_LIMIT_ENV = "JARVIS_STATUS_SMOKE_PRINT_LIMIT"
STATUS_SMOKE_VERBOSE_ENV = "JARVIS_STATUS_SMOKE_VERBOSE"
_STATUS_SMOKE_AUTH_TOKEN = "status-smoke-auth-token-32-chars-minimum"
_STATUS_SMOKE_AUTH_HEADER = "Basic " + base64.b64encode(
    f"jarvis:{_STATUS_SMOKE_AUTH_TOKEN}".encode("utf-8")
).decode("ascii")


def _status_smoke_print_limit() -> int:
    raw = os.getenv(STATUS_SMOKE_PRINT_LIMIT_ENV, "").strip()
    if not raw:
        return STATUS_SMOKE_PRINT_LIMIT
    try:
        value = int(raw)
    except ValueError:
        return STATUS_SMOKE_PRINT_LIMIT
    return max(0, value)


def _status_smoke_bounded_print_arg(arg: object) -> str:
    text = str(arg)
    if not _status_smoke_verbose() and ("\n" in text or len(text) > 500):
        return f"[status smoke detail omitted: {len(text)} chars; set {STATUS_SMOKE_VERBOSE_ENV}=1 for full payload]"
    limit = _status_smoke_print_limit()
    if limit <= 0 or len(text) <= limit:
        return text
    omitted = len(text) - limit
    return f"{text[:limit]}\n[status smoke output truncated: omitted {omitted} chars]"


def print(*args: object, **kwargs: object) -> None:
    builtins.print(*(_status_smoke_bounded_print_arg(arg) for arg in args), **kwargs)


def _status_smoke_uses_real_server() -> bool:
    return os.getenv(STATUS_SMOKE_REAL_SERVER_ENV, "").strip().lower() in {"1", "true", "yes", "on"}


def _status_smoke_verbose() -> bool:
    return os.getenv(STATUS_SMOKE_VERBOSE_ENV, "").strip().lower() in {"1", "true", "yes", "on"}


