def assert_status_exact_metadata_bool_helper() -> None:
    cases = [
        (True, False, True),
        (False, True, False),
        ("true", False, False),
        ("false", False, False),
        ("yes", False, False),
        (1, False, False),
        (["ready"], False, False),
        (None, True, True),
        (None, False, False),
    ]
    for value, default, expected in cases:
        observed = _status_metadata_bool(value, default=default)
        if observed is not expected:
            raise SystemExit(f"_status_metadata_bool accepted non-exact readiness value {value!r}: expected {expected}, got {observed}")


def assert_execution_case_status_payload_bools_are_exact() -> None:
    evidence_payload = _execution_case_evidence_preview_payload(
        {
            "evidence_preview_latest_handoff_present": "true",
            "evidence_preview_latest_handoff": {"next_command": "case evidence 1"},
        }
    )
    if evidence_payload.get("evidence_preview_latest_handoff_present") is not False:
        raise SystemExit(f"execution-case evidence payload accepted truthy handoff presence: {evidence_payload}")
    proof_payload = _execution_case_proof_alias_payload(
        {
            "execution_proof_handoff_present": "true",
            "execution_proof_handoff": {"next_command": "execution proof"},
        }
    )
    if proof_payload.get("execution_proof_handoff_present") is not False:
        raise SystemExit(f"execution-case proof payload accepted truthy handoff presence: {proof_payload}")


