def assert_setup_check_handoff_bools_are_exact() -> None:
    handoff = _setup_check_handoff(
        {
            "checks": 7,
            "setup_attention": ["sample"],
            "reads_environment": "true",
            "reads_secret_values": "true",
            "reads_env_file_contents": "true",
            "reads_google_credentials": "true",
            "reads_clipboard": "true",
            "env_file_configured": "true",
            "env_file_valid": "true",
            "google_credentials_valid": "true",
            "google_token_valid": "true",
            "storage_fallback_disabled": "true",
            "storage_fallback_disable_valid": "false",
            "google_connector_dependencies": {"docs": True, "calendar": False},
        }
    )
    expected_false_fields = [
        "reads_environment",
        "reads_secret_values",
        "reads_env_file_contents",
        "reads_google_credentials",
        "reads_clipboard",
        "env_file_configured",
        "env_file_valid",
        "google_credentials_valid",
        "google_token_valid",
        "storage_fallback_disabled",
    ]
    for field in expected_false_fields:
        if handoff.get(field) is not False:
            raise SystemExit(f"setup-check handoff accepted non-exact truthy metadata for {field}: {handoff}")
    if handoff.get("storage_fallback_disable_valid") is not True:
        raise SystemExit(f"setup-check handoff did not preserve conservative default for malformed fallback-disable validity: {handoff}")
    if handoff.get("checks") != 7 or handoff.get("attention_count") != 1:
        raise SystemExit(f"setup-check handoff lost non-boolean setup metadata: {handoff}")
    if handoff.get("google_connector_dependency_count") != 2 or handoff.get("google_connector_dependency_available_count") != 1:
        raise SystemExit(f"setup-check handoff lost Google dependency counts: {handoff}")


