def assert_fresh_review_boundary_token_api(data: dict, label: str, *, expected_source: str) -> None:
    metadata = data["metadata"]
    for key in [
        "fresh_review_boundary_token_sha256",
        "fresh_review_boundary_token_present",
        "fresh_review_boundary_token_rows",
        "fresh_review_boundary_token_row_count",
        "fresh_review_boundary_token_ready",
        "fresh_review_boundary_token_authorizes_action_now",
        "fresh_review_boundary_token_authorizes_local_safe_step",
        "fresh_review_boundary_token_authorizes_risky_work",
        "fresh_review_boundary_token_authorizes_unreviewed_followthrough",
        "fresh_review_boundary_token_authorizes_timebox_reuse",
        "fresh_review_boundary_token_authorizes_checkpoint_reuse",
        "fresh_review_boundary_token_authorizes_token_reuse",
        "fresh_review_boundary_token_authorizes_model_call",
        "fresh_review_boundary_token_authorizes_tool_execution",
        "fresh_review_boundary_token_authorizes_personal_data_read",
        "fresh_review_boundary_token_authorizes_external_side_effect",
        "fresh_review_boundary_token_reusable_for_next_review",
        "fresh_review_boundary_token_reusable_for_next_cycle",
        "next_review_requires_new_fresh_review_boundary_token",
    ]:
        if data.get(key) != metadata.get(key):
            raise SystemExit(f"{label} top-level fresh-review boundary field {key} diverged from metadata: {data}")
    token = str(metadata.get("fresh_review_boundary_token_sha256") or "")
    if len(token) != 64 or any(char not in "0123456789abcdefABCDEF" for char in token):
        raise SystemExit(f"{label} missed fresh-review boundary token: {metadata}")
    if metadata.get("fresh_review_boundary_token_present") is not True:
        raise SystemExit(f"{label} missed fresh-review boundary token presence: {metadata}")
    rows = metadata.get("fresh_review_boundary_token_rows") or []
    expected_rows = {
        "fresh_review_boundary_token": "present",
        "next_continuation_preflight": "fresh_operator_timebox_checkpoint_and_review_required",
        "prior_cycle_reuse_boundary": "prior_cycle_proof_only_not_reusable",
    }
    if metadata.get("fresh_review_boundary_token_row_count") != 3 or len(rows) != 3:
        raise SystemExit(f"{label} missed fresh-review boundary rows: {metadata}")
    if metadata.get("fresh_review_boundary_token_ready") is not True:
        raise SystemExit(f"{label} missed fresh-review boundary readiness: {metadata}")
    if not _fresh_review_boundary_token_ready(token, list(rows)):
        raise SystemExit(f"{label} fresh-review boundary failed production validator: {metadata}")
    tampered_ready_rows = [dict(row) for row in rows]
    tampered_ready_rows[0]["authorizes_tool_execution"] = True
    if _fresh_review_boundary_token_ready(token, tampered_ready_rows):
        raise SystemExit(f"{label} fresh-review boundary should reject tool-execution authority: {metadata}")
    tampered_ready_rows = [dict(row) for row in rows]
    tampered_ready_rows[0]["fresh_required"] = False
    if _fresh_review_boundary_token_ready(token, tampered_ready_rows):
        raise SystemExit(f"{label} fresh-review boundary should reject stale review rows: {metadata}")
    if {row.get("item") for row in rows} != set(expected_rows):
        raise SystemExit(f"{label} fresh-review boundary items diverged: {metadata}")
    for row in rows:
        item = row.get("item")
        if row.get("status") != expected_rows.get(item):
            raise SystemExit(f"{label} fresh-review boundary status diverged: {row}")
        if row.get("source") != expected_source:
            raise SystemExit(f"{label} fresh-review boundary source diverged: {row}")
        if row.get("token_sha256") != token:
            raise SystemExit(f"{label} fresh-review boundary token hash diverged: {row}")
        if (
            row.get("fresh_required") is not True
            or row.get("authorizes_action_now") is not False
            or row.get("authorizes_local_safe_step") is not False
            or row.get("authorizes_risky_work") is not False
            or row.get("authorizes_unreviewed_followthrough") is not False
            or row.get("authorizes_timebox_reuse") is not False
            or row.get("authorizes_checkpoint_reuse") is not False
            or row.get("authorizes_token_reuse") is not False
            or row.get("authorizes_model_call") is not False
            or row.get("authorizes_tool_execution") is not False
            or row.get("authorizes_personal_data_read") is not False
            or row.get("authorizes_external_side_effect") is not False
            or row.get("reusable_for_next_review") is not False
            or row.get("reusable_for_next_cycle") is not False
        ):
            raise SystemExit(f"{label} fresh-review boundary row should be non-authorizing: {row}")
    for key in [
        "fresh_review_boundary_token_authorizes_action_now",
        "fresh_review_boundary_token_authorizes_local_safe_step",
        "fresh_review_boundary_token_authorizes_risky_work",
        "fresh_review_boundary_token_authorizes_unreviewed_followthrough",
        "fresh_review_boundary_token_authorizes_timebox_reuse",
        "fresh_review_boundary_token_authorizes_checkpoint_reuse",
        "fresh_review_boundary_token_authorizes_token_reuse",
        "fresh_review_boundary_token_authorizes_model_call",
        "fresh_review_boundary_token_authorizes_tool_execution",
        "fresh_review_boundary_token_authorizes_personal_data_read",
        "fresh_review_boundary_token_authorizes_external_side_effect",
        "fresh_review_boundary_token_reusable_for_next_review",
        "fresh_review_boundary_token_reusable_for_next_cycle",
    ]:
        if metadata.get(key) is not False:
            raise SystemExit(f"{label} should report {key}=False: {metadata}")
    if metadata.get("next_review_requires_new_fresh_review_boundary_token") is not True:
        raise SystemExit(f"{label} missed next fresh-review token requirement: {metadata}")
    recomputed = _fresh_review_boundary_token_sha256(
        objective=str(metadata.get("objective") or ""),
        ledger_state=str(metadata.get("cycle_state") or ""),
        fresh_review_preflight_queue=list(metadata.get("fresh_review_preflight_queue") or []),
        fresh_review_contract_rows=list(metadata.get("fresh_review_contract_rows") or []),
        autonomy_cycle_ledger_token_sha256=str(metadata.get("autonomy_cycle_ledger_token_sha256") or ""),
        next_review_start_command=str(metadata.get("next_review_start_command") or ""),
    )
    if recomputed != token:
        raise SystemExit(f"{label} fresh-review boundary token should be reproducible: {metadata}")
    tampered_rows = list(metadata.get("fresh_review_contract_rows") or [])
    if tampered_rows:
        tampered_rows = [dict(row) for row in tampered_rows]
        tampered_rows[0]["authorizes_action_now"] = True
        tampered = _fresh_review_boundary_token_sha256(
            objective=str(metadata.get("objective") or ""),
            ledger_state=str(metadata.get("cycle_state") or ""),
            fresh_review_preflight_queue=list(metadata.get("fresh_review_preflight_queue") or []),
            fresh_review_contract_rows=tampered_rows,
            autonomy_cycle_ledger_token_sha256=str(metadata.get("autonomy_cycle_ledger_token_sha256") or ""),
            next_review_start_command=str(metadata.get("next_review_start_command") or ""),
        )
        if tampered == token:
            raise SystemExit(f"{label} fresh-review boundary token should bind action authority: {metadata}")


