        closure_state=str(token_metadata.get("closure_state") or ""),
        receipt_nonce=str(token_metadata.get("confirmation_receipt_nonce") or ""),
        handoff_state=str(token_metadata.get("handoff_state") or ""),
        handoff_ready=bool(token_metadata.get("handoff_ready")),
        command_intake_contract_sha256=str(token_metadata.get("voice_command_intake_contract_sha256") or ""),
        verification_receipt_sha256=str(token_metadata.get("verification_receipt_sha256") or ""),
        execution_health_sha256=str(token_metadata.get("execution_health_sha256") or ""),
        execution_audit_sha256=str(token_metadata.get("execution_audit_sha256") or ""),
        after_action_learning_sha256=str(token_metadata.get("after_action_learning_sha256") or ""),
        next_review_start_command=str(token_metadata.get("next_review_start_command") or ""),
        authorizes_personal_data_read=True,
