    tampered_handoff = _voice_post_run_closure_token_sha256(
        transcript_hash=str(token_metadata.get("transcript_hash") or ""),
        closure_state=str(token_metadata.get("closure_state") or ""),
        receipt_nonce=str(token_metadata.get("confirmation_receipt_nonce") or ""),
        handoff_state="VOICE_EXECUTION_HANDOFF_TAMPERED",
        handoff_ready=bool(token_metadata.get("handoff_ready")),
        command_intake_contract_sha256=str(token_metadata.get("voice_command_intake_contract_sha256") or ""),
        verification_receipt_sha256=str(token_metadata.get("verification_receipt_sha256") or ""),
        execution_health_sha256=str(token_metadata.get("execution_health_sha256") or ""),
        execution_audit_sha256=str(token_metadata.get("execution_audit_sha256") or ""),
        after_action_learning_sha256=str(token_metadata.get("after_action_learning_sha256") or ""),
        next_review_start_command=str(token_metadata.get("next_review_start_command") or ""),
    )
    if tampered_handoff == token:
        raise SystemExit(f"{label} voice post-run closure token should bind handoff state: {metadata}")
    tampered_contract = _voice_post_run_closure_token_sha256(
        transcript_hash=str(token_metadata.get("transcript_hash") or ""),
        closure_state=str(token_metadata.get("closure_state") or ""),
        receipt_nonce=str(token_metadata.get("confirmation_receipt_nonce") or ""),
        handoff_state=str(token_metadata.get("handoff_state") or ""),
        handoff_ready=bool(token_metadata.get("handoff_ready")),
        command_intake_contract_sha256="0" * 64,
        verification_receipt_sha256=str(token_metadata.get("verification_receipt_sha256") or ""),
        execution_health_sha256=str(token_metadata.get("execution_health_sha256") or ""),
        execution_audit_sha256=str(token_metadata.get("execution_audit_sha256") or ""),
        after_action_learning_sha256=str(token_metadata.get("after_action_learning_sha256") or ""),
        next_review_start_command=str(token_metadata.get("next_review_start_command") or ""),
    )
    if token_metadata.get("voice_command_intake_contract_sha256") != "0" * 64 and tampered_contract == token:
        raise SystemExit(f"{label} voice post-run closure token should bind command-intake contract: {metadata}")
    if token_metadata.get("voice_post_run_closure_token_binds_handoff_state") is not True:
        raise SystemExit(f"{label} should report post-run token binds handoff state: {metadata}")
    if token_metadata.get("voice_post_run_closure_token_binds_handoff_ready") is not True:
        raise SystemExit(f"{label} should report post-run token binds handoff readiness: {metadata}")
    if token_metadata.get("voice_post_run_closure_token_binds_command_intake_contract") is not True:
        raise SystemExit(f"{label} should report post-run token binds command-intake contract: {metadata}")


