def assert_voice_command_intake_contract_api(data: dict, label: str) -> None:
    metadata = data["metadata"]
    contract = str(data.get("voice_command_intake_contract_sha256") or "")
    if len(contract) != 64 or any(char not in "0123456789abcdefABCDEF" for char in contract):
        raise SystemExit(f"{label} missed top-level voice command-intake contract sha256: {data}")
    if data.get("transcript_sha256") != _transcript_sha256(str(metadata.get("transcript") or "")):
        raise SystemExit(f"{label} missed exact transcript sha256 binding: {data}")
    for key in VOICE_COMMAND_INTAKE_CONTRACT_API_KEYS:
        if data.get(key) != metadata.get(key):
            raise SystemExit(f"{label} top-level {key} diverged from metadata.")
    if data.get("voice_command_intake_contract_present") is not True or data.get("voice_command_intake_contract_ready") is not True:
        raise SystemExit(f"{label} missed command-intake contract ready flags: {data}")
    if data.get("next_voice_review_requires_fresh_command_intake_contract") is not True:
        raise SystemExit(f"{label} should require a fresh command-intake contract: {data}")
    for key in [
        "voice_command_intake_contract_authorizes_action_now",
        "voice_command_intake_contract_authorizes_model_call",
        "voice_command_intake_contract_authorizes_tool_execution",
        "voice_command_intake_contract_authorizes_approval",
        "voice_command_intake_contract_authorizes_routing",
        "voice_command_intake_contract_authorizes_transcript_mutation",
        "voice_command_intake_contract_authorizes_personal_data_read",
        "voice_command_intake_contract_authorizes_external_side_effect",
        "voice_command_intake_contract_reusable_for_next_voice_review",
    ]:
        if data.get(key) is not False:
            raise SystemExit(f"{label} command-intake contract should report {key}=False: {data}")
    recomputed = _voice_command_intake_contract_sha256(
        transcript=str(metadata.get("transcript") or ""),
        transcript_sha256=str(data.get("transcript_sha256") or ""),
        privacy_receipt_id=str(data.get("voice_command_intake_contract_privacy_receipt_id") or ""),
        confirmation_receipt_id=str(data.get("voice_command_intake_contract_confirmation_receipt_id") or ""),
        confirmation_receipt_nonce=str(data.get("voice_command_intake_contract_confirmation_receipt_nonce") or ""),
        route_gate_state=str(data.get("voice_command_intake_contract_route_gate_state") or ""),
        route_proof_bundle_state=str(data.get("voice_command_intake_contract_route_proof_bundle_state") or ""),
        runtime_bridge_state=str(data.get("voice_command_intake_contract_runtime_bridge_state") or ""),
        proof_commands=list(data.get("voice_command_intake_contract_proof_commands") or []),
    )
    if recomputed != contract:
        raise SystemExit(f"{label} command-intake contract should be reproducible: {data}")
    tampered = _voice_command_intake_contract_sha256(
        transcript=str(metadata.get("transcript") or ""),
        transcript_sha256=str(data.get("transcript_sha256") or ""),
        privacy_receipt_id=str(data.get("voice_command_intake_contract_privacy_receipt_id") or ""),
        confirmation_receipt_id=str(data.get("voice_command_intake_contract_confirmation_receipt_id") or ""),
        confirmation_receipt_nonce=str(data.get("voice_command_intake_contract_confirmation_receipt_nonce") or ""),
        route_gate_state=str(data.get("voice_command_intake_contract_route_gate_state") or ""),
        route_proof_bundle_state=str(data.get("voice_command_intake_contract_route_proof_bundle_state") or ""),
        runtime_bridge_state=str(data.get("voice_command_intake_contract_runtime_bridge_state") or ""),
        proof_commands=list(data.get("voice_command_intake_contract_proof_commands") or []),
        authorizes_routing=True,
    )
    if tampered == contract:
        raise SystemExit(f"{label} command-intake contract should bind routing authority: {data}")


def assert_execution_learning_api_aliases(data: dict, metadata: dict, label: str) -> None:
    for key in [
        "execution_learning_proof_queue",
        "execution_learning_proof_queue_count",
        "execution_learning_next_proof_command",
    ]:
        if key not in data or key not in metadata:
            raise SystemExit(f"{label} missed explicit top-level execution learning proof alias {key}: {data}")
    if data.get("execution_learning_proof_queue") != metadata.get("execution_learning_proof_queue"):
        raise SystemExit(f"{label} top-level execution learning proof queue diverged: {data}")
    if data.get("execution_learning_proof_queue_count") != metadata.get("execution_learning_proof_queue_count"):
        raise SystemExit(f"{label} top-level execution learning proof queue count diverged: {data}")
    if data.get("execution_learning_next_proof_command") != metadata.get("execution_learning_next_proof_command"):
        raise SystemExit(f"{label} top-level execution learning next proof alias diverged: {data}")
    actionable_commands = metadata.get("execution_learning_actionable_required_commands") or []
    if actionable_commands:
        for key in [
            "execution_learning_evidence_command",
            "execution_learning_after_action_learning_command",
            "execution_learning_actionable_required_commands",
            "execution_learning_actionable_required_command_count",
            "execution_learning_actionable_proof_queue",
            "execution_learning_actionable_proof_queue_count",
            "execution_learning_actionable_next_required_command",
            "execution_learning_actionable_next_proof_command",
            "execution_learning_next_evidence_command",
        ]:
            if data.get(key) != metadata.get(key):
                raise SystemExit(f"{label} top-level actionable execution learning field {key} diverged: {data}")
        if data.get("execution_learning_actionable_proof_queue") != actionable_commands:
            raise SystemExit(f"{label} top-level actionable learning proof queue diverged: {data}")
        if data.get("execution_learning_next_evidence_command") != actionable_commands[0]:
            raise SystemExit(f"{label} top-level actionable learning next evidence command diverged: {data}")


