def assert_execution_health_learning_handoff_api(data: dict, label: str) -> None:
    metadata = data["metadata"]
    for key in [
        "execution_health_learning_target_run_id",
        "execution_health_learning_target_tool",
        "execution_health_verification_handoff_command",
        "execution_health_recovery_handoff_command",
        "execution_health_learning_handoff_command",
        "execution_health_learning_closure_command",
        "execution_health_execution_learning_closure_command",
        "execution_learning_closure_command",
        "execution_learning_state",
        "execution_learning_blocks_completion_claim",
        "execution_learning_missing",
        "execution_learning_missing_count",
        "execution_learning_required_commands",
        "execution_learning_next_required_command",
        "execution_learning_target_run_id",
        "execution_learning_target_tool_name",
    ]:
        if data.get(key) != metadata.get(key):
            raise SystemExit(f"{label} top-level execution-health learning handoff {key} diverged from metadata.")
    target_run_id = data.get("execution_health_learning_target_run_id")
    if not target_run_id or not data.get("execution_health_learning_target_tool"):
        raise SystemExit(f"{label} missed execution-health learning target: {data}")
    expected_commands = [
        f"verification receipt {target_run_id}",
        f"execution recovery packet {target_run_id}",
        f"after-action learning packet {target_run_id}",
        f"execution learning closure {target_run_id}",
    ]
    for command in expected_commands:
        if command not in data.get("execution_health_next_commands", metadata.get("execution_health_next_commands", [])):
            raise SystemExit(f"{label} missed handoff command in execution-health queue: {command} in {data}")
    if data.get("execution_learning_state") not in {"LEARNING_DEBT_AFTER_FAILURE", "LEARNING_REVIEW_REQUIRED"}:
        raise SystemExit(f"{label} missed execution learning debt state: {data}")
    if data.get("execution_learning_blocks_completion_claim") is not True:
        raise SystemExit(f"{label} should block completion on execution learning debt: {data}")
    if data.get("execution_learning_target_run_id") != target_run_id:
        raise SystemExit(f"{label} execution learning target diverged from handoff target: {data}")
    if data.get("execution_learning_missing_count", 0) < 1 or not data.get("execution_learning_missing"):
        raise SystemExit(f"{label} missed execution learning missing proofs: {data}")
    learning_commands = data.get("execution_learning_required_commands") or []
    expected_learning_closure = f"execution learning closure {target_run_id}"
    if data.get("execution_health_learning_closure_command") != expected_learning_closure:
        raise SystemExit(f"{label} missed top-level execution learning closure handoff command: {data}")
    if data.get("execution_learning_closure_command") != expected_learning_closure:
        raise SystemExit(f"{label} missed execution learning closure command: {data}")
    if expected_learning_closure not in learning_commands:
        raise SystemExit(f"{label} missed execution learning closure command in execution learning queue: {data}")
    if not any(str(command).startswith("after-action learning packet") for command in learning_commands):
        raise SystemExit(f"{label} missed after-action learning command in execution learning queue: {data}")
    if learning_commands and data.get("execution_learning_next_required_command") != learning_commands[0]:
        raise SystemExit(f"{label} missed first execution learning proof command: {data}")
    for key in [
        "execution_learning_proof_queue",
        "execution_learning_proof_queue_count",
        "execution_learning_next_proof_command",
    ]:
        if key not in data or key not in metadata:
            raise SystemExit(f"{label} missed explicit execution learning proof alias {key}: {data}")
    if data.get("execution_learning_proof_queue") != metadata.get("execution_learning_proof_queue"):
        raise SystemExit(f"{label} execution learning proof queue diverged from metadata: {data}")
    if data.get("execution_learning_proof_queue_count") != len(data.get("execution_learning_proof_queue") or []):
        raise SystemExit(f"{label} execution learning proof queue count diverged: {data}")
    if data.get("execution_learning_next_proof_command") != metadata.get("execution_learning_next_proof_command"):
        raise SystemExit(f"{label} execution learning next proof alias diverged: {data}")
    for command in learning_commands:
        if command not in data.get("execution_health_next_commands", metadata.get("execution_health_next_commands", [])):
            raise SystemExit(f"{label} missed execution learning command in health queue: {command} in {data}")
    if data.get("execution_health_repeated_failure_count", metadata.get("execution_health_repeated_failure_count", 0)) > 0:
        queue = data.get("execution_health_failure_promotion_queue", metadata.get("execution_health_failure_promotion_queue", [])) or []
        for key in [
            "execution_health_failure_promotion_command",
            "execution_health_failure_implementation_command",
            "execution_health_failure_apply_contract_command",
        ]:
            command = data.get(key, metadata.get(key))
            if not command:
                raise SystemExit(f"{label} missed execution-health failure promotion key {key}: {data}")
            if command not in queue or command not in data.get("execution_health_next_commands", metadata.get("execution_health_next_commands", [])):
                raise SystemExit(f"{label} missed failure promotion command in queues: {command} in {data}")
        if data.get("execution_health_failure_promotion_queue_count", metadata.get("execution_health_failure_promotion_queue_count")) != len(queue):
            raise SystemExit(f"{label} missed failure promotion queue count: {data}")
    closure_required_commands = data.get(
        "execution_health_recovery_closure_required_commands",
        metadata.get("execution_health_recovery_closure_required_commands", []),
    ) or []
    recovery_closure_blocks_auto = (
        data.get(
            "execution_health_recovery_closure_blocks_auto_execution",
            metadata.get("execution_health_recovery_closure_blocks_auto_execution"),
        )
        is True
    )
    recovery_closure_blocks_completion = data.get("execution_health_recovery_closure_blocks_completion_claim") is True
    for key in [
        "execution_health_recovery_closure_blocks_completion_claim",
        "execution_health_recovery_closure_target_run_id",
        "execution_health_recovery_closure_target_tool_name",
        "execution_health_recovery_closure_target_verification_receipts",
        "execution_health_recovery_closure_target_recovery_packets",
        "execution_health_recovery_closure_target_after_action_learning_packets",
    ]:
        if data.get(key) != metadata.get(key):
            raise SystemExit(f"{label} top-level recovery completion handoff {key} diverged from metadata: {data}")
    if data.get("execution_health_recovery_closure_target_run_id") != target_run_id:
        raise SystemExit(f"{label} recovery closure target should mirror execution-health target run: {data}")
    if data.get("execution_health_recovery_closure_target_tool_name") != data.get("execution_health_learning_target_tool"):
        raise SystemExit(f"{label} recovery closure target should mirror execution-health target tool: {data}")
    if recovery_closure_blocks_auto or recovery_closure_blocks_completion:
        if not recovery_closure_blocks_auto:
            raise SystemExit(f"{label} should block auto-run while recovery closure is incomplete: {data}")
        if not recovery_closure_blocks_completion:
            raise SystemExit(f"{label} should block completion claims while recovery closure is incomplete: {data}")
        if not closure_required_commands:
            raise SystemExit(f"{label} missed recovery closure proof queue while recovery closure blocks execution: {data}")
    else:
        if closure_required_commands:
            raise SystemExit(f"{label} exposed recovery closure proof queue without active recovery closure: {data}")
        if data.get("execution_health_recovery_closure_next_required_command") not in {"", None}:
            raise SystemExit(f"{label} exposed recovery closure next command without active recovery closure: {data}")
        if data.get("execution_health_recovery_closure_next_proof_command") not in {"", None}:
            raise SystemExit(f"{label} exposed recovery closure proof command without active recovery closure: {data}")
    if closure_required_commands and data.get("execution_health_next_command", metadata.get("execution_health_next_command")) != closure_required_commands[0]:
        raise SystemExit(f"{label} should route next command to first recovery-closure proof: {data}")
    next_commands = data.get("execution_health_next_commands", metadata.get("execution_health_next_commands", []))
    if closure_required_commands and next_commands[: len(closure_required_commands)] != closure_required_commands:
        raise SystemExit(f"{label} should place recovery-closure proof commands first in the queue: {data}")


def assert_doctor_recovery_handoff_api(data: dict, label: str) -> None:
    metadata = data["metadata"]
    for key in [
        "doctor_recovery_closure_state",
        "doctor_recovery_closure_missing",
        "doctor_recovery_closure_missing_count",
        "doctor_recovery_closure_required_commands",
        "doctor_recovery_closure_next_required_command",
        "doctor_recovery_closure_proof_queue",
        "doctor_recovery_closure_proof_queue_count",
        "doctor_recovery_closure_next_proof_command",
        "doctor_recovery_closure_ready_to_retry",
        "doctor_recovery_closure_blocks_completion_claim",
        "doctor_recovery_closure_checklist_command",
        "doctor_recovery_closure_should_open_checklist",
        "doctor_execution_learning_state",
        "doctor_execution_learning_missing",
        "doctor_execution_learning_missing_count",
        "doctor_execution_learning_required_commands",
        "doctor_execution_learning_next_required_command",
        "doctor_execution_learning_blocks_completion_claim",
        "doctor_execution_learning_actionable_required_commands",
        "doctor_execution_learning_actionable_required_command_count",
        "doctor_execution_learning_actionable_next_required_command",
        "doctor_execution_learning_actionable_proof_queue",
        "doctor_execution_learning_actionable_proof_queue_count",
        "doctor_execution_learning_actionable_next_proof_command",
        "doctor_execution_learning_next_evidence_command",
        "doctor_audit_readability_review_required",
        "doctor_audit_readability_review_commands",
        "doctor_audit_readability_review_command_count",
        "doctor_audit_readability_review_next_command",
        "doctor_unreadable_recent_tool_run_rows",
        "doctor_completion_proof_queue",
        "doctor_completion_proof_queue_count",
        "doctor_completion_next_proof_command",
    ]:
        if data.get(key) != metadata.get(key):
            raise SystemExit(f"{label} top-level doctor recovery handoff {key} diverged from metadata.")
    commands = data.get("doctor_recovery_closure_required_commands") or []
    recovery_proof_queue = data.get("doctor_recovery_closure_proof_queue") or []
    recovery_closure_blocks = data.get("doctor_recovery_closure_blocks_completion_claim") is True
    if recovery_closure_blocks:
        if data.get("doctor_recovery_closure_checklist_command") != "recovery closure checklist":
            raise SystemExit(f"{label} missed doctor recovery closure checklist command: {data}")
        if data.get("doctor_recovery_closure_should_open_checklist") is not True:
            raise SystemExit(f"{label} should recommend opening the recovery closure checklist: {data}")
        if not commands:
            raise SystemExit(f"{label} missed doctor recovery closure proof queue: {data}")
        if data.get("doctor_recovery_closure_next_required_command") != commands[0]:
            raise SystemExit(f"{label} missed doctor recovery closure next proof command: {data}")
        if recovery_proof_queue != commands:
            raise SystemExit(f"{label} doctor recovery closure proof queue diverged: {data}")
        if data.get("doctor_recovery_closure_proof_queue_count") != len(recovery_proof_queue):
            raise SystemExit(f"{label} doctor recovery closure proof queue count diverged: {data}")
        if data.get("doctor_recovery_closure_next_proof_command") != recovery_proof_queue[0]:
            raise SystemExit(f"{label} doctor missed next recovery closure proof alias: {data}")
        if data.get("doctor_recovery_closure_missing_count", 0) < 1 or not data.get("doctor_recovery_closure_missing"):
            raise SystemExit(f"{label} missed doctor recovery closure missing proof details: {data}")
        for command in ["verification receipt", "execution recovery packet", "after-action learning packet"]:
            if not any(str(item).startswith(command) for item in commands):
                raise SystemExit(f"{label} doctor recovery queue missed {command}: {data}")
        if not any("recovery closure" in str(blocker) for blocker in data.get("doctor_completion_blockers", [])):
            raise SystemExit(f"{label} doctor blockers missed recovery closure: {data}")
    else:
        if commands or recovery_proof_queue:
            raise SystemExit(f"{label} exposed doctor recovery closure commands without completion-blocking recovery: {data}")
        if data.get("doctor_recovery_closure_next_required_command") not in {"", None}:
            raise SystemExit(f"{label} exposed doctor recovery closure next command without completion-blocking recovery: {data}")
        if data.get("doctor_recovery_closure_next_proof_command") not in {"", None}:
            raise SystemExit(f"{label} exposed doctor recovery closure proof command without completion-blocking recovery: {data}")
    if data.get("doctor_execution_learning_blocks_completion_claim") is not True:
        raise SystemExit(f"{label} doctor missed execution learning completion blocker: {data}")
    learning_commands = data.get("doctor_execution_learning_required_commands") or []
    learning_proof_queue = data.get("doctor_execution_learning_proof_queue") or []
    learning_actionable_commands = data.get("doctor_execution_learning_actionable_required_commands") or []
    learning_actionable_queue = data.get("doctor_execution_learning_actionable_proof_queue") or []
    if not learning_commands or data.get("doctor_execution_learning_next_required_command") != learning_commands[0]:
        raise SystemExit(f"{label} doctor missed execution learning proof queue: {data}")
    for key in [
        "doctor_execution_learning_proof_queue",
        "doctor_execution_learning_proof_queue_count",
        "doctor_execution_learning_next_proof_command",
    ]:
        if key not in data or key not in metadata:
            raise SystemExit(f"{label} doctor missed explicit execution learning proof alias {key}: {data}")
    if data.get("doctor_execution_learning_proof_queue") != metadata.get("doctor_execution_learning_proof_queue"):
        raise SystemExit(f"{label} doctor execution learning proof queue diverged: {data}")
    if data.get("doctor_execution_learning_proof_queue_count") != len(learning_proof_queue):
        raise SystemExit(f"{label} doctor execution learning proof queue count diverged: {data}")
    if data.get("doctor_execution_learning_next_proof_command") != metadata.get("doctor_execution_learning_next_proof_command"):
        raise SystemExit(f"{label} doctor execution learning next proof alias diverged: {data}")
    if not learning_actionable_commands:
        raise SystemExit(f"{label} doctor missed execution learning actionable queue: {data}")
    if learning_actionable_queue != learning_actionable_commands:
        raise SystemExit(f"{label} doctor execution learning actionable queue diverged: {data}")
    if data.get("doctor_execution_learning_actionable_required_command_count") != len(learning_actionable_commands):
        raise SystemExit(f"{label} doctor execution learning actionable required count diverged: {data}")
    if data.get("doctor_execution_learning_actionable_proof_queue_count") != len(learning_actionable_queue):
        raise SystemExit(f"{label} doctor execution learning actionable proof count diverged: {data}")
    if data.get("doctor_execution_learning_actionable_next_required_command") != learning_actionable_queue[0]:
        raise SystemExit(f"{label} doctor execution learning actionable next required diverged: {data}")
    if data.get("doctor_execution_learning_actionable_next_proof_command") != learning_actionable_queue[0]:
        raise SystemExit(f"{label} doctor execution learning actionable next proof diverged: {data}")
    if data.get("doctor_execution_learning_next_evidence_command") != learning_actionable_queue[0]:
        raise SystemExit(f"{label} doctor execution learning next evidence command diverged: {data}")
    after_action_indexes = [
        index
        for index, command in enumerate(learning_actionable_queue)
        if str(command).startswith("after-action learning packet")
    ]
    closure_indexes = [
        index
        for index, command in enumerate(learning_actionable_queue)
        if str(command).startswith("execution learning closure")
    ]
    if after_action_indexes and closure_indexes and after_action_indexes[0] > closure_indexes[0]:
        raise SystemExit(f"{label} doctor actionable queue should put after-action evidence before closure: {data}")
    if data.get("doctor_execution_learning_missing_count", 0) < 1 or not data.get("doctor_execution_learning_missing"):
        raise SystemExit(f"{label} doctor missed execution learning missing proofs: {data}")
    if not any("execution learning debt" in str(blocker) for blocker in data.get("doctor_completion_blockers", [])):
        raise SystemExit(f"{label} doctor blockers missed execution learning debt: {data}")
    completion_proof_queue = data.get("doctor_completion_proof_queue") or []
    if not completion_proof_queue:
        raise SystemExit(f"{label} doctor missed completion proof queue: {data}")
    if data.get("doctor_completion_proof_queue_count") != len(completion_proof_queue):
        raise SystemExit(f"{label} doctor completion proof queue count diverged from queue length: {data}")
    if data.get("doctor_completion_next_proof_command") != completion_proof_queue[0]:
        raise SystemExit(f"{label} doctor missed first completion proof command: {data}")
    audit_readability_commands = data.get("doctor_audit_readability_review_commands") or []
    if data.get("doctor_audit_readability_review_required"):
        expected_audit_readability = ["storage status", "recent tool runs", "execution health report"]
        if audit_readability_commands != expected_audit_readability:
            raise SystemExit(f"{label} doctor audit-readability queue diverged: {data}")
        if data.get("doctor_audit_readability_review_next_command") != audit_readability_commands[0]:
            raise SystemExit(f"{label} doctor missed audit-readability next command: {data}")
        if data.get("doctor_unreadable_recent_tool_run_rows", 0) < 1:
            raise SystemExit(f"{label} doctor missed unreadable recent tool-run count: {data}")
        if not any("unreadable recent tool run" in str(blocker) for blocker in data.get("doctor_completion_blockers", [])):
            raise SystemExit(f"{label} doctor blockers missed audit-readability issue: {data}")
    else:
        if audit_readability_commands or data.get("doctor_audit_readability_review_next_command"):
            raise SystemExit(f"{label} doctor exposed audit-readability commands without required flag: {data}")
    if data.get("doctor_audit_readability_review_command_count") != len(audit_readability_commands):
        raise SystemExit(f"{label} doctor audit-readability queue count diverged: {data}")
    for command in audit_readability_commands:
        if command not in completion_proof_queue:
            raise SystemExit(f"{label} doctor completion proof queue missed audit-readability command {command!r}: {data}")
    storage_readiness_queue = data.get("doctor_storage_readiness_next_commands") or []
    if data.get("doctor_storage_readiness_blocks_completion_claim") and storage_readiness_queue:
        if completion_proof_queue[: len(storage_readiness_queue)] != storage_readiness_queue:
            raise SystemExit(f"{label} doctor completion proof queue should preserve full storage recovery ladder: {data}")
    for command in recovery_proof_queue + learning_actionable_queue:
        if command not in completion_proof_queue:
            raise SystemExit(f"{label} doctor completion proof queue missed proof command {command!r}: {data}")
    after_action_indexes = [
        index
        for index, command in enumerate(completion_proof_queue)
        if str(command).startswith("after-action learning packet")
    ]
    closure_indexes = [
        index
        for index, command in enumerate(completion_proof_queue)
        if str(command).startswith("execution learning closure")
    ]
    if after_action_indexes and closure_indexes and after_action_indexes[0] > closure_indexes[0]:
        raise SystemExit(f"{label} doctor completion proof queue should put after-action evidence before closure: {data}")
    approval_indexes = [
        index
        for index, command in enumerate(completion_proof_queue)
        if str(command).startswith("approval readiness")
    ]
    if data.get("pending_approvals") and approval_indexes and after_action_indexes and approval_indexes[0] > after_action_indexes[0]:
        raise SystemExit(f"{label} doctor completion proof queue should put pending approval review before learning evidence: {data}")
    for command in ["harness completion", "completion audit", "evidence ledger", "completion claim gate"]:
        if command not in completion_proof_queue:
            raise SystemExit(f"{label} doctor completion proof queue missed {command}: {data}")


def assert_doctor_agi_handoff_api(data: dict, label: str) -> None:
    metadata = data["metadata"]
    for key in [
        "doctor_agi_next_gate",
        "doctor_agi_next_selection_source",
        "doctor_agi_next_selection_reason",
        "doctor_agi_next_canonical_selector_command",
        "doctor_agi_next_deliberate_focus_override",
        "doctor_agi_next_target_title",
        "doctor_agi_next_build_command",
        "doctor_agi_next_evidence_closure_commands",
        "doctor_agi_next_evidence_closure_command_count",
        "doctor_agi_next_focused_verification_commands",
        "doctor_agi_next_focused_verification_command_count",
        "doctor_agi_next_likely_files",
        "doctor_agi_next_likely_file_count",
        "doctor_agi_next_target_file_integrity_status",
        "doctor_agi_next_target_files_checked",
        "doctor_agi_next_target_files_exist",
        "doctor_agi_next_missing_target_files",
        "doctor_agi_next_missing_target_file_count",
        "doctor_agi_next_target_integrity_blocks_start",
        "doctor_agi_next_acceptance_checks",
        "doctor_agi_next_acceptance_check_count",
        "doctor_agi_next_build_packet_ready_for_review",
    ]:
        if data.get(key) != metadata.get(key):
            raise SystemExit(f"{label} top-level doctor AGI handoff {key} diverged from metadata.")
    if not data.get("doctor_agi_next_target_title"):
        raise SystemExit(f"{label} missed doctor AGI target title: {data}")
    if data.get("doctor_agi_next_gate") not in str(data.get("doctor_agi_next_build_command") or ""):
        raise SystemExit(f"{label} missed doctor AGI build command: {data}")
    if data.get("doctor_agi_next_selection_source") not in {
        "next_step_doctor_default_gate",
        "harness_dynamic_registry",
        "next_step_doctor_default_gate_after_selector_error",
    }:
        raise SystemExit(f"{label} missed recognized doctor AGI selection source: {data}")
    if data.get("doctor_agi_next_canonical_selector_command") != data.get("doctor_agi_next_build_command"):
        raise SystemExit(f"{label} doctor AGI canonical selector command diverged: {data}")
    if data.get("doctor_agi_next_deliberate_focus_override") is not False:
        raise SystemExit(f"{label} doctor AGI handoff should not claim an operator focus override: {data}")
    if data.get("doctor_agi_next_likely_file_count") != len(data.get("doctor_agi_next_likely_files") or []):
        raise SystemExit(f"{label} doctor AGI file count diverged: {data}")
    if data.get("doctor_agi_next_evidence_closure_command_count") != len(data.get("doctor_agi_next_evidence_closure_commands") or []):
        raise SystemExit(f"{label} doctor AGI closure count diverged: {data}")
    if data.get("doctor_agi_next_focused_verification_command_count") != len(data.get("doctor_agi_next_focused_verification_commands") or []):
        raise SystemExit(f"{label} doctor AGI verification count diverged: {data}")
    if data.get("doctor_agi_next_acceptance_check_count") != len(data.get("doctor_agi_next_acceptance_checks") or []):
        raise SystemExit(f"{label} doctor AGI acceptance count diverged: {data}")
    if bool(data.get("doctor_agi_next_target_integrity_blocks_start")) is data.get("doctor_agi_next_target_files_exist"):
        raise SystemExit(f"{label} doctor AGI target-integrity blocker diverged: {data}")
    expected_ready = bool(
        data.get("doctor_agi_next_target_files_exist")
        and data.get("doctor_agi_next_focused_verification_commands")
        and data.get("doctor_agi_next_acceptance_checks")
    )
    if data.get("doctor_agi_next_build_packet_ready_for_review") is not expected_ready:
        raise SystemExit(f"{label} doctor AGI readiness flag diverged: {data}")


